{
  "name": "@aerovato/operator-opencode-v2",
  "version": "2.3.0",
  "description": "Operator Memory adapter for OpenCode V2.",
  "license": "BSD-3-Clause",
  "author": "Aerovato Research",
  "homepage": "https://github.com/aerovato/operator-memory#readme",
  "bugs": {
    "url": "https://github.com/aerovato/operator-memory/issues"
  },
  "type": "module",
  "main": "dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./server": "./dist/index.js",
    "./rpc": "./dist/notifications.js",
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "memory",
    "plugin"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/aerovato/operator-memory.git",
    "directory": "packages/opencode-v2"
  },
  "engines": {
    "node": ">=20"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bun ./scripts/build.ts",
    "prepack": "bun run build"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.0.14",
    "@opentui/core": ">=0.5.10",
    "@opentui/solid": ">=0.5.10",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@aerovato/operator-core": "workspace:*",
    "@opencode/plugin": "2.0.14",
    "@opentui/core": "0.5.10",
    "@opentui/solid": "0.5.10",
    "solid-js": "1.9.12"
  }
}
